sys_script.script:
(function executeRule(current, previous /*null when async*/) {
	try{

		// This manager will be inserted in the equipment manager table in case of blank 
		var defaultManagerSysId = '41c03f4253c1f210829a70c0a0490ee2' ;
		// "sys_id" of "hussien.m"

		// Case of requester manager is blank
		if(current.requester.manager.nil){

			// Add hussien.m to the manager
			current.manager = defaultManagerSysId ;
			// update record
			current.update() ; 

		} 
	// otherwise
		else{
			gs.addErrorMessage('not Null manager: ' + current.requester.first_name) ; 
			// Get the requester in user table
			var userObj = new GlideRecord('sys_user') ; 
			// Get his manager 
			var managerId = userObj.get(current.getValue('manager')) ;
			// Set value of manager in equipment table
			current.setValue('manager' , managerId) ; 
			// current.update() ;
		}
	}catch(error){
		gs.addErrorMessage("run-time error: " + error) ; 
	}


})(current, previous);
